function firstIndexWhere(nums, isYes) {
  let lo = 0;
  let hi = nums.length;
  while (lo < hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (isYes(nums[mid])) {
      hi = mid;
    } else {
      lo = mid + 1;
    }
  }
  return lo;
}

function firstAndLast(nums, target) {
  const first = firstIndexWhere(nums, (value) => value >= target);
  if (first === nums.length || nums[first] !== target) return [-1, -1];
  const afterLast = firstIndexWhere(nums, (value) => value > target);
  return [first, afterLast - 1];
}

