  const nums = Array.from({ length: rand(12) }, () => rand(7) - 3).sort((a, b) => a - b);
  const t = rand(9) - 4;
  assertEqual(firstAndLast(nums, t), brute(nums, t), JSON.stringify(nums) + ' target=' + t);
